	output reg [4:0] id_dst_addr,
	output reg id_gpr_we_,
	output reg [3:0] id_exp_code
);always @(posedge clk or posedge reset) begin
		if (reset) begin
			id_pc <= 32'h00000000;
			id_en <= 1'b0;
			id_alu_op <= 4'b0000;
			id_alu_in_0 <= 32'h00000000;
			id_alu_in_1 <= 32'h00000000;
