			if (stall) begin
				// do nothing
			end else if (flush) begin
				id_pc <= 32'h00000000;
				id_en <= 1'b0;
				id_alu_op <= 4'b0000;
				id_alu_in_0 <= 32'h00000000;
				id_alu_in_1 <= 32'h00000000;
