);// Define internal signals
  reg [7:0] tx_data;
  reg [7:0] rx_data;
  reg tx_valid;
  reg rx_valid;

  // Transmitter block
  always @(posedge clk or posedge rst) begin
    if (rst) begin
      tx_data <= 8'b0;
      tx_valid <= 1'b0;
    end else if (valid_in) begin
      tx_data <= data_in;
      tx_valid <= 1'b1;
    end else if (tx_valid) begin
      tx_data <= 8'b0;
      tx_valid <= 1'b0;
    end
  end

  // Receiver block
  always @(posedge clk or posedge rst) begin
    if (rst) begin
      rx_data <= 8'b0;
      rx_valid <= 1'b0;
      valid_out <= 1'b0;  // Initialize valid_out on reset
    end else if (rx_valid) begin
      data_out <= rx_data;
      valid_out <= 1'b1;
      rx_valid <= 1'b0;
    end else begin
      valid_out <= 1'b0;  // Reset valid_out if not valid
    end
  end

