description:
Implement a circuit that performs 4-bit multiplication. This module takes two 4-bit inputs, MULTIPLICAND and MULTIPLIER, and produces an 8-bit output, PRODUCT. The multiplication is carried out using a combinational logic approach that shifts the MULTIPLICAND left based on the active bits of the MULTIPLIER and accumulates the result, effectively calculating the product of the two inputs.
module top_module(
    input [3:0] MULTIPLICAND,
    input [3:0] MULTIPLIER,
    output reg [7:0] PRODUCT
);

code:
module top_module(
    input [3:0] MULTIPLICAND,
    input [3:0] MULTIPLIER,
    output reg [7:0] PRODUCT
);reg [3:0] m;
reg [7:0] p;

always @(*) begin
    p = 0;
    for (m = 0; m < 4; m = m + 1) begin
        if (MULTIPLIER[m] == 1) begin
            p = p + (MULTIPLICAND << m);
        end
    end
end

assign PRODUCT = p;

endmodule

