Implement the Verilog module based on the following description.
Build a 5-bit pseudo-random binary sequence generator with synchronous active high reset signal.
// (1) reset: Resets the generator to a predefined seed value.
// (2) q: The value of the generated sequence.

module top_module(
    input clk,
    input reset,
    output reg [4:0] q);

code:
module top_module(
    input clk,
    input reset,
    output reg [4:0] q
);

    initial begin
        // Initial seed value
        q = 5'b10101;
    end

    always @(posedge clk) begin
        if (reset) begin
            // Synchronous reset: Set to predefined seed value
            q <= 5'b10101;
        end else begin
            // Generate pseudo-random sequence
            q <= {q[3:0], q[4] ^ q[2]};
        end
    end

endmodule

